CREATE TABLE IF NOT EXISTS public.miles_versions (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), scenario_id VARCHAR(10) NOT NULL UNIQUE, category VARCHAR(20) NOT NULL CHECK (category IN ('panic', 'depression', 'cravings', 'isolation', 'progress')), scenario_name VARCHAR(255) NOT NULL, user_message TEXT NOT NULL, bua_response TEXT NOT NULL, ra_response TEXT NOT NULL, bua_retention_impact DECIMAL(5, 2), bua_ltv_impact INTEGER, ra_churn_impact DECIMAL(5, 2), ra_ltv_impact INTEGER, criteria JSONB NOT NULL, system_prompt_override TEXT, version_number INTEGER DEFAULT 1, is_active BOOLEAN DEFAULT true, created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW());
